// РОЗВІДКА: закрити вікно помилки і спробувати меню. ТІЛЬКИ НАВІГАЦІЯ.
const { chromium } = require('playwright');
const fs = require('fs');
(async () => {
  const env = {};
  for (const l of fs.readFileSync('/root/unitex-finrep/secure/odata_write.env','utf8').split('\n')) {
    const m = l.match(/^\s*([A-Z_]+)\s*=\s*(.+?)\s*$/); if (m) env[m[1]] = m[2];
  }
  const browser = await chromium.launch({ args:['--no-sandbox','--ignore-certificate-errors'] });
  const ctx = await browser.newContext({ ignoreHTTPSErrors:true, viewport:{width:1500,height:950}, locale:'uk-UA' });
  const page = await ctx.newPage();
  page.on('dialog', d => d.accept());
  await page.goto('https://unitex.rdport.net:29231/DB/', { waitUntil:'load', timeout:60000 });
  await page.waitForTimeout(7000);
  await page.fill('#userName', env.ODATA_USER);
  await page.fill('#userPassword', env.ODATA_PASS);
  await page.press('#userPassword','Enter');
  await page.waitForTimeout(35000);

  const close = await page.$('text="Закрити"');
  if (close) { await close.click({timeout:8000}).catch(e=>console.log('клік Закрити не вийшов')); await page.waitForTimeout(6000); }
  let t = await page.evaluate(() => document.body.innerText);
  console.log('ПІСЛЯ «Закрити»: помилка на екрані?', t.includes('не підтримується') ? 'ТАК' : 'НІ');

  const m = await page.$('text="Експедирування"');
  if (m) { await m.click({timeout:8000}).catch(()=>{}); await page.waitForTimeout(8000); }
  t = await page.evaluate(() => document.body.innerText);
  console.log('ЕКРАН:');
  console.log(t.replace(/\n{2,}/g,'\n').slice(0,2200));
  await page.screenshot({ path:'/root/webbot/shots/32-nav2.png' });
  await browser.close();
})().catch(e => { console.log('ПОМИЛКА:', String(e).slice(0,300)); process.exit(1); });
EOJS
cd /root/webbot && timeout 250 node nav2.js 2>&1 | tail -50
